-- =============================================================
-- 03_META/03_SHEET_COLUMNS_DMF0082_DIV82.sql
--   DMF0082 division 82 컬럼 노출 토큰 보정 (81 과 동수: 23=23 / 10=10)
--   사고: 82 가 40 경로로 취급되어 컬럼 노출 불일치
--   방식: NOT EXISTS INSERT + UPDATE 동반 (hook deploy-package-completeness §1.7)
--         — INSERT 만 하면 클라우드의 '기존 잘못된 행'을 고치지 못함
--   대상 2 행 / 멱등
-- 감사컬럼 규약: CREATED_BY/LAST_UPDATED_BY = 'admin' (메모리 meta_audit_column_admin_only)
-- =============================================================
SET DEFINE OFF

-- [DMF0082 / FcstNPrice / SENDER_NAME]
INSERT INTO SCM_MST_SHEET_COLUMNS (PROGRAM_ID,SHEET_NAME,COLUMN_NAME,COLUMN_LABEL_NAME,SORT_ORDER_NO,DATA_SORT_METHOD_CODE,SMALL_CLASS_LABEL_NAME,LARGE_CLASS_LABEL_NAME,FIXED_FLAG,COLUMN_WIDTH,CELL_CONTROL_OBJECT_TYPE_CODE,CELL_COMBO_DATA_TYPE,DATA_SCALE_NUMBER,DATA_MAX_LENGTH,HORIZONTAL_ALIGN_CODE,UPPERCASE_APPLY_FLAG,VISIBLE_FLAG,DIVISION_ID,DEFAULT_FLAG,USER_SELECTABLE_FLAG,VALID_YN,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10,INPUT_TP_CD)
  SELECT 'DMF0082','FcstNPrice','SENDER_NAME','Sender Name',360,'ASC','Sender Name','Sender Name',' ',80,'FPTextBox',' ',NULL,NULL,'C',' ','Y','40,81,81_UC,81_HM,81_ST,81_HD,81_HG,82','N','Y','Y','dsiol',TO_DATE('20250205154313','YYYYMMDDHH24MISS'),'admin',TO_DATE('20260730201836','YYYYMMDDHH24MISS'),'40,81,81_GM',' ',' ',' ',' ',' ',NULL,NULL,NULL,NULL,'S' FROM DUAL
   WHERE NOT EXISTS (SELECT 1 FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='DMF0082' AND SHEET_NAME='FcstNPrice' AND COLUMN_NAME='SENDER_NAME');
UPDATE SCM_MST_SHEET_COLUMNS SET COLUMN_LABEL_NAME='Sender Name', SORT_ORDER_NO=360, DATA_SORT_METHOD_CODE='ASC', SMALL_CLASS_LABEL_NAME='Sender Name', LARGE_CLASS_LABEL_NAME='Sender Name', FIXED_FLAG=' ', COLUMN_WIDTH=80, CELL_CONTROL_OBJECT_TYPE_CODE='FPTextBox', CELL_COMBO_DATA_TYPE=' ', DATA_SCALE_NUMBER=NULL, DATA_MAX_LENGTH=NULL, HORIZONTAL_ALIGN_CODE='C', UPPERCASE_APPLY_FLAG=' ', VISIBLE_FLAG='Y', DIVISION_ID='40,81,81_UC,81_HM,81_ST,81_HD,81_HG,82', DEFAULT_FLAG='N', USER_SELECTABLE_FLAG='Y', VALID_YN='Y', CREATED_BY='dsiol', LAST_UPDATED_BY='admin', ATTRIBUTE1='40,81,81_GM', ATTRIBUTE2=' ', ATTRIBUTE3=' ', ATTRIBUTE4=' ', ATTRIBUTE5=' ', ATTRIBUTE6=' ', ATTRIBUTE7=NULL, ATTRIBUTE8=NULL, ATTRIBUTE9=NULL, ATTRIBUTE10=NULL, INPUT_TP_CD='S'
 WHERE PROGRAM_ID='DMF0082' AND SHEET_NAME='FcstNPrice' AND COLUMN_NAME='SENDER_NAME';

-- [DMF0082 / Sales Price Save All / PLANT_SITE_ID]
INSERT INTO SCM_MST_SHEET_COLUMNS (PROGRAM_ID,SHEET_NAME,COLUMN_NAME,COLUMN_LABEL_NAME,SORT_ORDER_NO,DATA_SORT_METHOD_CODE,SMALL_CLASS_LABEL_NAME,LARGE_CLASS_LABEL_NAME,FIXED_FLAG,COLUMN_WIDTH,CELL_CONTROL_OBJECT_TYPE_CODE,CELL_COMBO_DATA_TYPE,DATA_SCALE_NUMBER,DATA_MAX_LENGTH,HORIZONTAL_ALIGN_CODE,UPPERCASE_APPLY_FLAG,VISIBLE_FLAG,DIVISION_ID,DEFAULT_FLAG,USER_SELECTABLE_FLAG,VALID_YN,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10,INPUT_TP_CD)
